#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for(int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y) {
        assert(x > 0 && y > 0 && x + y < n);
        ops.push_back({x, y});
        vector<int> np;
        for(int i = n - y; i < n; i++) np.push_back(p[i]);
        for(int i = x; i < n - y; i++) np.push_back(p[i]);
        for(int i = 0; i < x; i++) np.push_back(p[i]);
        p = np;
    };

    for(int placed = 0; placed < n - 1; placed++) {
        // Find where element (placed+1) is
        int pos = -1;
        for(int i = placed; i < n; i++) {
            if(p[i] == placed + 1) { pos = i; break; }
        }
        if(pos == placed) continue;

        int remaining = n - placed; // elements from index placed..n-1 not yet placed

        // We work in the subproblem but operations are global.
        // Step 1: bring element to position n-1
        if(pos != n - 1) {
            // We want to move p[pos] to position n-1.
            // Use x = pos + 1, y = n - 1 - pos
            // But x + y = n, need x + y < n
            // So use x = pos + 1, y = n - pos - 2 (if > 0)
            // After: element at pos = x-1 goes to position n-1 (end of prefix block)
            // Middle has 1 element: p[pos+1..pos+1] = p[n-y-1]
            if(n - pos - 2 > 0) {
                doOp(pos + 1, n - pos - 2);
            } else {
                // pos == n - 2, so y would be 0. Use a different approach.
                // Move element at n-2 to n-1: swap last two effectively
                // x = n - 2, y = 1: new = [p[n-1], middle_empty_if_x+y=n-1, p[0..n-3]]
                // Actually middle = p[n-2..n-2] since x=n-2, n-y=n-1, so middle = p[n-2..n-2]
                // new = [p[n-1], p[n-2], p[0..n-3]]
                // Element at n-2 goes to position 1, not n-1. 
                // Instead: x=1, y=1 if n>=3
                // new = [p[n-1], p[1..n-2], p[0]]
                // Element at n-2 stays at n-2. Not helpful.
                // x = n-1, y = 1: x+y=n, invalid.
                // x=1, y=n-2: new=[p[2..n-1], p[1], p[0]]. Element at n-2 goes to n-3.
                // Just use: x=pos+1=n-1, invalid since x+y>=n. 
                // Trick: x=1,y=1 rotates. Then refind.
                doOp(1, 1);
                pos = -1;
                for(int i = placed; i < n; i++) if(p[i]==placed+1){pos=i;break;}
                if(pos == placed) continue;
                if(pos != n-1 && n-pos-2 > 0) {
                    doOp(pos+1, n-pos-2);
                } else if(pos == n-1) { /* ok */ }
                else { doOp(1,1); continue; } // retry
            }
            pos = n - 1;
        }

        // Step 2: element at n-1, move to position 'placed'
        if(placed == 0) {
            if(n - 2 > 0) doOp(1, n - 2);
        } else {
            doOp(placed, 1);
        }
    }

    printf("%d\n", (int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n", x, y);
}
